  1	// Drives system Chrome through every library x task and records what a reader and a developer would observe.
  2	// Usage: node probe.mjs [phase ...]   phases: look, empty, a11y, env, perf   (default: all)
  3	// LIBS=chartjs-tuned,echarts-tuned node probe.mjs perf   runs a subset
  4	import { chromium } from 'playwright-core';
  5	import { PNG } from 'pngjs';
  6	import fs from 'node:fs';
  7	
  8	const BASE = 'http://localhost:4173/';
  9	const LIBS = ['chartjs', 'recharts', 'd3', 'echarts', 'highcharts', 'apexcharts', 'plotly', 'nivo', 'mui', 'uplot'];
 10	const only = process.env.LIBS?.split(',') ?? LIBS;
 11	const phases = process.argv.slice(2).length ? process.argv.slice(2) : ['look', 'empty', 'a11y', 'env', 'perf'];
 12	fs.mkdirSync('shots', { recursive: true });
 13	const resultsFile = 'results.json';
 14	const results = fs.existsSync(resultsFile) ? JSON.parse(fs.readFileSync(resultsFile, 'utf8')) : {};
 15	const save = () => fs.writeFileSync(resultsFile, JSON.stringify(results, null, 1));
 16	const sleep = ms => new Promise(r => setTimeout(r, ms));
 17	
 18	const browser = await chromium.launch({ channel: 'chrome', headless: true });
 19	results._env = { chrome: browser.version(), date: new Date().toISOString(), headless: true };
 20	
 21	async function open(ctxOpts, lib, task, extra = '', settle = 1800, timeout = 60000) {
 22	  const ctx = await browser.newContext({ viewport: { width: 800, height: 520 }, timezoneId: 'UTC', locale: 'en-US', ...ctxOpts });
 23	  const page = await ctx.newPage();
 24	  const logs = [];
 25	  page.on('console', m => { if (['warning', 'error'].includes(m.type())) logs.push(`${m.type()}: ${m.text().slice(0, 300)}`); });
 26	  page.on('pageerror', e => logs.push(`pageerror: ${String(e).slice(0, 300)}`));
 27	  await page.goto(`${BASE}?lib=${lib}&task=${task}${extra}`);
 28	  let res;
 29	  try { res = await (await page.waitForFunction(() => window.__result, null, { timeout })).jsonValue(); }
 30	  catch { res = { timeout: true }; }
 31	  if (settle) await sleep(settle);
 32	  return { ctx, page, logs, res };
 33	}
 34	
 35	const domStats = () => {
 36	  const el = document.getElementById('chart');
 37	  const all = [...el.querySelectorAll('*')];
 38	  const attrs = ['role', 'aria-label', 'aria-labelledby', 'aria-describedby', 'aria-hidden', 'aria-live', 'tabindex', 'aria-roledescription'];
 39	  const marked = all.filter(n => attrs.some(a => n.hasAttribute(a))).slice(0, 40).map(n => {
 40	    const o = { tag: n.tagName.toLowerCase() };
 41	    for (const a of attrs) if (n.hasAttribute(a)) o[a] = n.getAttribute(a).slice(0, 160);
 42	    return o;
 43	  });
 44	  const texts = [...el.querySelectorAll('svg text')].filter(t => t.textContent.trim());
 45	  const sizes = {}, fills = {};
 46	  for (const t of texts) { const cs = getComputedStyle(t); sizes[cs.fontSize] = (sizes[cs.fontSize] ?? 0) + 1; fills[cs.fill] = (fills[cs.fill] ?? 0) + 1; }
 47	  const big = el.querySelector('svg, canvas');
 48	  return {
 49	    nodes: all.length, svg: el.querySelectorAll('svg').length, canvas: el.querySelectorAll('canvas').length,
 50	    svgTitle: el.querySelectorAll('svg title').length, svgDesc: el.querySelectorAll('svg desc').length,
 51	    tables: el.querySelectorAll('table').length, markedCount: all.filter(n => attrs.some(a => n.hasAttribute(a))).length, marked,
 52	    canvasFallback: [...el.querySelectorAll('canvas')].map(c => c.textContent.trim().slice(0, 120)),
 53	    svgTextSizes: sizes, svgTextFills: fills, mainWidth: big ? Math.round(big.getBoundingClientRect().width) : null,
 54	    mainHeight: big ? Math.round(big.getBoundingClientRect().height) : null,
 55	  };
 56	};
 57	
 58	const shot = async (page, name) => { const p = `shots/${name}.png`; await page.locator('#chart').screenshot({ path: p }); return p; };
 59	const diffRatio = (a, b) => {
 60	  const A = PNG.sync.read(a), B = PNG.sync.read(b);
 61	  if (A.width !== B.width || A.height !== B.height) return 1;
 62	  let n = 0;
 63	  for (let i = 0; i < A.data.length; i += 4) if (Math.abs(A.data[i] - B.data[i]) + Math.abs(A.data[i + 1] - B.data[i + 1]) + Math.abs(A.data[i + 2] - B.data[i + 2]) > 30) n++;
 64	  return n / (A.data.length / 4);
 65	};
 66	const bodyLines = page => page.evaluate(() => document.body.innerText.split('\n').map(s => s.trim()).filter(Boolean));
 67	
 68	for (const lib of only) {
 69	  const R = (results[lib] ??= {});
 70	
 71	  if (phases.includes('look')) for (const task of ['trend', 'bars', 'parts', 'dirty']) {
 72	    const { ctx, page, logs, res } = await open({}, lib, task);
 73	    const out = { res, logs };
 74	    if (!res.unsupported) {
 75	      out.dom = await page.evaluate(domStats);
 76	      out.aria = (await page.locator('#chart').ariaSnapshot().catch(e => 'ERR ' + e)).slice(0, 2500);
 77	      await shot(page, `${task}-${lib}`);
 78	    }
 79	    R[task] = out; save(); await ctx.close();
 80	    console.log(lib, task, JSON.stringify(res).slice(0, 120), logs.length ? `logs:${logs.length}` : '');
 81	  }
 82	
 83	  if (phases.includes('empty')) {
 84	    // the query returned no rows: what does the reader see, and what does assistive technology get?
 85	    const { ctx, page, logs, res } = await open({}, lib, 'empty');
 86	    R.empty = { res, logs: logs.slice(0, 4), text: (await bodyLines(page)).filter(l => !['before', 'after'].includes(l)).slice(0, 12),
 87	      aria: (await page.locator('#chart').ariaSnapshot().catch(e => 'ERR ' + e)).slice(0, 600) };
 88	    await shot(page, `empty-${lib}`); await ctx.close(); save();
 89	    console.log(lib, 'empty', JSON.stringify(R.empty.text).slice(0, 160), logs.length ? `logs:${logs.length}` : '');
 90	  }
 91	
 92	  if (phases.includes('a11y')) {
 93	    const { ctx, page } = await open({}, lib, 'trend');
 94	    const k = { stops: [] };
 95	    await page.focus('#before');
 96	    for (let i = 0; i < 40; i++) {
 97	      await page.keyboard.press('Tab');
 98	      const a = await page.evaluate(() => {
 99	        const e = document.activeElement, c = document.getElementById('chart');
100	        if (e.id === 'after') return 'AFTER';
101	        if (!c.contains(e)) return 'OUTSIDE:' + e.tagName;
102	        const r = e.getBoundingClientRect(), cs = getComputedStyle(e);
103	        return { tag: e.tagName.toLowerCase(), role: e.getAttribute('role'), label: (e.getAttribute('aria-label') ?? e.textContent ?? '').trim().slice(0, 120), cls: String(e.className?.baseVal ?? e.className).slice(0, 60), box: [Math.round(r.width), Math.round(r.height)], outline: cs.outlineStyle + ' ' + cs.outlineWidth };
104	      });
105	      if (a === 'AFTER') break;
106	      k.stops.push(a);
107	    }
108	    // arrow-key exploration from the first stop inside the chart
109	    await page.focus('#before'); await page.keyboard.press('Tab');
110	    const before = await bodyLines(page);
111	    const describe = () => page.evaluate(() => {
112	      const e = document.activeElement;
113	      const live = [...document.querySelectorAll('[aria-live]')].map(n => n.textContent.trim().slice(0, 200)).filter(Boolean);
114	      return { active: (e.getAttribute?.('aria-label') ?? e.textContent ?? '').trim().slice(0, 160), tag: e.tagName.toLowerCase(), live };
115	    });
116	    k.arrows = [];
117	    for (const key of ['ArrowRight', 'ArrowRight', 'ArrowDown', 'Enter']) { await page.keyboard.press(key); await sleep(250); k.arrows.push({ key, ...(await describe()) }); }
118	    const after = await bodyLines(page);
119	    k.newTextAfterKeys = after.filter(l => !before.includes(l)).slice(0, 12);
120	    await shot(page, `kbd-${lib}`);
121	    R.keyboard = k; await ctx.close();
122	
123	    // pointer hover: what does the default tooltip say?
124	    for (const [tz, tag] of [['UTC', 'utc'], ['America/Los_Angeles', 'la']]) {
125	      const o = await open({ timezoneId: tz }, lib, 'trend');
126	      const b0 = await bodyLines(o.page);
127	      const box = await o.page.locator('#chart').boundingBox();
128	      await o.page.mouse.move(box.x + box.width * 0.3, box.y + box.height * 0.5);
129	      await o.page.mouse.move(box.x + box.width * 0.5, box.y + box.height * 0.45, { steps: 8 });
130	      await sleep(500);
131	      const b1 = await bodyLines(o.page);
132	      R[`hover_${tag}`] = { newText: b1.filter(l => !b0.includes(l)).slice(0, 14) };
133	      await shot(o.page, `hover-${tag}-${lib}`);
134	      await o.ctx.close();
135	    }
136	    save(); console.log(lib, 'a11y', k.stops.length, 'tab stops');
137	  }
138	
139	  if (phases.includes('env')) {
140	    // container resize
141	    { const { ctx, page } = await open({}, lib, 'trend');
142	      await page.evaluate(() => { document.getElementById('chart').style.width = '360px'; });
143	      await sleep(900);
144	      R.resize = await page.evaluate(() => { const c = document.getElementById('chart'); const b = c.querySelector('svg, canvas'); return { mainWidth: Math.round(b.getBoundingClientRect().width), scrollWidth: c.scrollWidth }; });
145	      await shot(page, `resize-${lib}`); await ctx.close(); }
146	    // born narrow (phone width)
147	    { const { ctx, page } = await open({}, lib, 'trend', '&w=340'); await shot(page, `narrow-${lib}`); await ctx.close(); }
148	    // dark scheme
149	    { const { ctx, page } = await open({ colorScheme: 'dark' }, lib, 'trend'); await shot(page, `dark-${lib}`); await ctx.close(); }
150	    // motion: compare an early frame with the settled frame, with and without prefers-reduced-motion
151	    for (const rm of ['no-preference', 'reduce']) {
152	      const { ctx, page } = await open({ reducedMotion: rm }, lib, 'bars', '', 0);
153	      const early = await page.locator('#chart').screenshot();
154	      await sleep(2500);
155	      const late = await page.locator('#chart').screenshot();
156	      R[`motion_${rm}`] = { earlyVsSettledDiff: +diffRatio(early, late).toFixed(4) };
157	      await ctx.close();
158	    }
159	    save(); console.log(lib, 'env', R.resize, R['motion_no-preference'], R.motion_reduce);
160	  }
161	
162	  if (phases.includes('perf')) {
163	    R.scale = {};
164	    for (const n of [10000, 100000, 1000000]) {
165	      const prev = R.scale[n / 10];
166	      if (prev && (prev.timeout || prev.error || prev.toPaintMs > 8000)) { R.scale[n] = { skipped: 'previous size too slow' }; continue; }
167	      const runs = [];
168	      for (let i = 0; i < 3; i++) { const { ctx, res } = await open({}, lib, 'scale', `&n=${n}`, 0, 45000); runs.push(res); await ctx.close(); if (res.timeout || res.error) break; }
169	      const ok = runs.filter(r => r.toPaintMs).map(r => r.toPaintMs).sort((a, b) => a - b);
170	      R.scale[n] = ok.length ? { toPaintMs: +ok[Math.floor(ok.length / 2)].toFixed(1), runs: ok.map(v => +v.toFixed(1)) } : runs[runs.length - 1];
171	      save(); console.log(lib, 'scale', n, JSON.stringify(R.scale[n]).slice(0, 160));
172	    }
173	    { const { ctx, res, logs } = await open({}, lib, 'stream', '', 0, 90000);
174	      for (const key in res) if (typeof res[key] === 'number') res[key] = +res[key].toFixed(2);
175	      R.stream = { ...res, logs: logs.slice(0, 3) }; await ctx.close(); save(); console.log(lib, 'stream', JSON.stringify(R.stream).slice(0, 200)); }
176	  }
177	}
178	save();
179	await browser.close();

 1	import { LineChart, Line, BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
 2	import { mount } from './_react.jsx';
 3	
 4	export const meta = { name: 'Recharts', pkg: 'recharts' };
 5	// Recharts has no default palette (every Line is #3182bd, every Pie sector #808080) and no title component.
 6	// Colors below are the ones used throughout the official examples.
 7	const colors = ['#8884d8', '#82ca9d', '#ffc658'];
 8	const pieColors = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042'];
 9	const day = t => new Date(t).toLocaleDateString(); // without a tickFormatter a time axis prints raw epoch numbers
10	
11	const TimeLines = ({ rows, names, yTitle }) => (
12	  <ResponsiveContainer width="100%" height="100%">
13	    <LineChart data={rows}>
14	      <CartesianGrid strokeDasharray="3 3" />
15	      <XAxis dataKey="t" type="number" scale="time" domain={['dataMin', 'dataMax']} tickFormatter={day} />
16	      <YAxis label={yTitle && { value: yTitle, angle: -90, position: 'insideLeft' }} />
17	      <Tooltip labelFormatter={day} />
18	      <Legend />
19	      {names.map((n, i) => <Line key={n} dataKey={n} stroke={colors[i]} />)}
20	    </LineChart>
21	  </ResponsiveContainer>
22	);
23	
24	export function trend(el, d) {
25	  const rows = d.t.map((t, i) => Object.fromEntries([['t', t], ...d.series.map(s => [s.name, s.values[i]])]));
26	  const r = mount(el, p => <TimeLines {...p} />);
27	  r.draw({ rows, names: d.series.map(s => s.name), yTitle: d.yTitle });
28	  return r;
29	}
30	
31	export function bars(el, d) {
32	  const rows = d.categories.map((name, i) => ({ name, [d.name]: d.values[i] }));
33	  const r = mount(el, () => (
34	    <ResponsiveContainer width="100%" height="100%">
35	      <BarChart data={rows}>
36	        <CartesianGrid strokeDasharray="3 3" />
37	        <XAxis dataKey="name" />
38	        <YAxis label={{ value: d.yTitle, angle: -90, position: 'insideLeft' }} />
39	        <Tooltip />
40	        <Bar dataKey={d.name} fill={colors[0]} />
41	      </BarChart>
42	    </ResponsiveContainer>
43	  ));
44	  r.draw();
45	  return r;
46	}
47	
48	export function parts(el, d) {
49	  const rows = d.labels.map((name, i) => ({ name, value: d.values[i] }));
50	  const r = mount(el, () => (
51	    <ResponsiveContainer width="100%" height="100%">
52	      <PieChart>
53	        <Pie data={rows} dataKey="value" nameKey="name" innerRadius="50%" label>
54	          {rows.map((row, i) => <Cell key={row.name} fill={pieColors[i % pieColors.length]} />)}
55	        </Pie>
56	        <Tooltip />
57	        <Legend />
58	      </PieChart>
59	    </ResponsiveContainer>
60	  ));
61	  r.draw();
62	  return r;
63	}
64	
65	export function dirty(el, d) {
66	  const rows = d.categories.map((name, i) => ({ name, [d.name]: d.values[i] }));
67	  const r = mount(el, () => (
68	    <ResponsiveContainer width="100%" height="100%">
69	      <LineChart data={rows}>
70	        <XAxis dataKey="name" />
71	        <YAxis />
72	        <Tooltip />
73	        <Line dataKey={d.name} stroke={colors[0]} />
74	      </LineChart>
75	    </ResponsiveContainer>
76	  ));
77	  r.draw();
78	  return r;
79	}
80	
81	export function scale(el, d) {
82	  const rows = d.t.map((t, i) => ({ t, [d.name]: d.y[i] }));
83	  const r = mount(el, p => <TimeLines {...p} />);
84	  r.rows = rows; r.names = [d.name];
85	  r.draw({ rows, names: r.names });
86	  return r;
87	}
88	
89	export function stream(el, d) {
90	  const r = scale(el, d);
91	  r.push = (x, y) => { r.rows = [...r.rows.slice(1), { t: x, [d.name]: y }]; r.draw({ rows: r.rows, names: r.names }); };
92	  return r;
93	}
 1	import { LineChart } from '@mui/x-charts/LineChart';
 2	import { BarChart } from '@mui/x-charts/BarChart';
 3	import { PieChart } from '@mui/x-charts/PieChart';
 4	import { mount } from './_react.jsx';
 5	
 6	export const meta = { name: 'MUI X Charts', pkg: '@mui/x-charts' };
 7	// No title component. Without width/height props the chart fills its container.
 8	
 9	const Lines = ({ t, series, yTitle }) => (
10	  <LineChart xAxis={[{ data: t, scaleType: 'time' }]} yAxis={[{ label: yTitle }]} series={series} />
11	);
12	
13	export function trend(el, d) {
14	  const r = mount(el, p => <Lines {...p} />);
15	  r.draw({ t: d.t.map(v => new Date(v)), yTitle: d.yTitle, series: d.series.map(s => ({ label: s.name, data: s.values })) });
16	  return r;
17	}
18	
19	export function bars(el, d) {
20	  const r = mount(el, () => (
21	    <BarChart xAxis={[{ data: d.categories }]} yAxis={[{ label: d.yTitle }]} series={[{ label: d.name, data: d.values }]} />
22	  ));
23	  r.draw();
24	  return r;
25	}
26	
27	export function parts(el, d) {
28	  const data = d.labels.map((label, id) => ({ id, label, value: d.values[id] }));
29	  const r = mount(el, () => <PieChart series={[{ data, innerRadius: 70 }]} />);
30	  r.draw();
31	  return r;
32	}
33	
34	export function dirty(el, d) {
35	  const r = mount(el, () => (
36	    <LineChart xAxis={[{ data: d.categories, scaleType: 'point' }]} series={[{ label: d.name, data: d.values }]} />
37	  ));
38	  r.draw();
39	  return r;
40	}
