42	export function scale(el, d) {
43	  const r = mount(el, p => <Lines {...p} />);
44	  r.t = d.t.map(v => new Date(v)); r.y = d.y.slice();
45	  r.draw({ t: r.t, series: [{ label: d.name, data: r.y }] });
46	  return r;
