49	export function stream(el, d) {
50	  const r = scale(el, d);
51	  r.push = (x, y) => { r.t = [...r.t.slice(1), new Date(x)]; r.y = [...r.y.slice(1), y]; r.draw({ t: r.t, series: [{ label: d.name, data: r.y }] }); };
52	  return r;
53	}
 1	import { createRoot } from 'react-dom/client';
 2	import { flushSync } from 'react-dom';
 3	
 4	// Mounts synchronously so that create/update timings include React's render and commit.
 5	export function mount(el, render) {
 6	  const root = createRoot(el);
 7	  const draw = props => flushSync(() => root.render(render(props)));
 8	  return { draw, destroy: () => root.unmount() };
 9	}

 1	import uPlot from 'uplot';
 2	import 'uplot/dist/uPlot.min.css';
 3	
 4	export const meta = { name: 'uPlot', pkg: 'uplot' };
 5	// uPlot needs explicit pixel sizes (no auto-resize), explicit stroke colors (no palette), and x in seconds.
 6	const size = el => ({ width: el.clientWidth, height: el.clientHeight - 80 }); // title and legend sit outside `height`
 7	const colors = ['red', 'green', 'blue']; // the colors used in uPlot's README example
 8	const secs = t => t.map(v => v / 1000);
 9	
10	export function trend(el, d) {
11	  const u = new uPlot({
12	    title: d.title, ...size(el),
13	    series: [{}, ...d.series.map((s, i) => ({ label: s.name, stroke: colors[i] }))],
14	    axes: [{}, { label: d.yTitle }],
15	  }, [secs(d.t), ...d.series.map(s => s.values)], el);
16	  return { u, destroy: () => u.destroy() };
17	}
18	
19	export function bars(el, d) {
20	  const idx = d.categories.map((_, i) => i);
21	  const u = new uPlot({
22	    title: d.title, ...size(el),
23	    scales: { x: { time: false, range: [-0.5, idx.length - 0.5] } },
24	    axes: [{ splits: () => idx, values: (u, splits) => splits.map(i => d.categories[i]) }, { label: d.yTitle }],
25	    series: [{}, { label: d.name, stroke: 'blue', fill: 'rgba(0,0,255,0.3)', paths: uPlot.paths.bars({ size: [0.6, 100] }) }],
26	  }, [idx, d.values], el);
27	  return { u, destroy: () => u.destroy() };
28	}
29	
30	export const parts = null; // no pie/donut in uPlot
31	
32	export function dirty(el, d) {
33	  const idx = d.categories.map((_, i) => i);
34	  const u = new uPlot({
35	    title: d.title, ...size(el),
36	    scales: { x: { time: false } },
37	    axes: [{ splits: () => idx, values: (u, splits) => splits.map(i => d.categories[i]) }, {}],
38	    series: [{}, { label: d.name, stroke: 'blue' }],
39	  }, [idx, d.values], el);
40	  return { u, destroy: () => u.destroy() };
41	}
42	
43	export function scale(el, d) {
44	  const data = [secs(d.t), d.y.slice()];
45	  const u = new uPlot({ title: d.title, ...size(el), series: [{}, { label: d.name, stroke: 'blue' }] }, data, el);
46	  return { u, data, destroy: () => u.destroy() };
47	}
48	
49	export function stream(el, d) {
50	  const h = scale(el, d);
51	  h.push = (x, y) => { h.data[0].push(x / 1000); h.data[0].shift(); h.data[1].push(y); h.data[1].shift(); h.u.setData(h.data); };
52	  return h;
53	}
 1	import { Chart } from 'chart.js/auto';
 2	import 'chartjs-adapter-date-fns'; // a date adapter is required before a time scale works
 3	
 4	export const meta = { name: 'Chart.js', pkg: 'chart.js' };
 5	const canvas = el => el.appendChild(document.createElement('canvas'));
 6	// maintainAspectRatio:false is needed for the chart to fill a fixed-height container
 7	const base = d => ({ maintainAspectRatio: false, plugins: { title: { display: true, text: d.title } } });
 8	
 9	export function trend(el, d) {
10	  const chart = new Chart(canvas(el), {
11	    type: 'line',
12	    data: { labels: d.t, datasets: d.series.map(s => ({ label: s.name, data: s.values })) },
13	    options: { ...base(d), scales: { x: { type: 'time' }, y: { title: { display: true, text: d.yTitle } } } },
14	  });
15	  return { chart, destroy: () => chart.destroy() };
16	}
17	
18	export function bars(el, d) {
19	  const chart = new Chart(canvas(el), {
20	    type: 'bar',
21	    data: { labels: d.categories, datasets: [{ label: d.name, data: d.values }] },
22	    options: { ...base(d), scales: { y: { title: { display: true, text: d.yTitle } } } },
23	  });
24	  return { chart, destroy: () => chart.destroy() };
25	}
26	
27	export function parts(el, d) {
28	  const chart = new Chart(canvas(el), {
29	    type: 'doughnut',
30	    data: { labels: d.labels, datasets: [{ label: d.name, data: d.values }] },
31	    options: base(d),
