 6	const LIBS = ['chartjs', 'recharts', 'd3', 'echarts', 'highcharts', 'apexcharts', 'plotly', 'nivo', 'mui', 'uplot'];
 7	const browser = await chromium.launch({ channel: 'chrome', headless: true });
 8	const grab = async (lib, task) => {
 9	  const page = await browser.newPage({ viewport: { width: 800, height: 520 } });
10	  await page.goto(`http://localhost:4173/?lib=${lib}&task=${task}`);
11	  await page.waitForFunction(() => window.__result); await page.waitForTimeout(1800);
12	  const colors = await page.evaluate(task => {
13	    const h = window.__handle, el = document.getElementById('chart');
14	    const norm = c => { const x = document.createElement('canvas').getContext('2d'); x.fillStyle = c; return x.fillStyle; };
15	    if (h?.chart?.data?.datasets) { const d = h.chart.data.datasets; return (task === 'parts' ? d[0].backgroundColor : d.map(s => s.borderColor)).map(norm); }
16	    if (h?.chart?.getOption) return h.chart.getOption().color.slice(0, task === 'parts' ? 6 : 3).map(norm);
17	    if (h?.u) return h.u.series.slice(1).map(s => norm(s._stroke ?? s.stroke(h.u)));
18	    // SVG: big filled shapes for the donut, long stroked paths for lines; keep first-seen order
19	    const seen = [];
20	    for (const p of el.querySelectorAll('svg path, svg circle')) {
21	      const cs = getComputedStyle(p), b = p.getBBox?.() ?? { width: 0, height: 0 };
22	      if (p.closest('[class*=legend]')) continue;
23	      const c = task === 'parts' ? cs.fill : cs.stroke;
24	      if (!c || c === 'none' || c.includes('rgba(0, 0, 0, 0)')) continue;
25	      if (/rgba\(/.test(c) || c === 'rgb(255, 255, 255)') continue; // skip translucent overlays and white separators
26	      if (task === 'parts' ? (p.tagName !== 'path' || b.width < 3 || b.height < 3) : (p.tagName !== 'path' || b.width < 200 || cs.fill !== 'none')) continue;
27	      const n = norm(c); if (!seen.includes(n)) seen.push(n);
28	    }
29	    return seen;
30	  }, task);
31	  await page.close();
32	  return colors;
