13	const lum = ([r, g, b]) => 0.2126 * r + 0.7152 * g + 0.0722 * b;
14	const contrast = (a, b) => { const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p); return (x + 0.05) / (y + 0.05); };
15	const hex = rgb => '#' + rgb.map(v => Math.round(255 * gam(Math.min(1, Math.max(0, v)))).toString(16).padStart(2, '0')).join('');
